=== FILE: lifo4_fcov.sv ===
// lifo4_fcov: functional coverage model for the lifo4 stack block.
// Built from the approved requirement-to-plan matrix (traceability_matrix.md, plan-audit stage).
//
// CLOSURE STATEMENT
// Sampling: every rising edge of clk. The values used are the port values just before the edge.
//   count is the stack occupancy before the edge.
//   Occupancy class: EMPTY means count == 0, FULL means count == 4, MID means 1 <= count <= 3.
//   Operation: PUSH means push alone, POP means pop alone, BOTH means push and pop together.
//   The matrix plans no bin for "neither push nor pop".
//   Cross and occupancy bins are sampled only when rst_n is high, because each rule applies with rst_n high.
//
// Planned bins (15):
//   bin  0  PUSH x EMPTY  - LIFO-PUSH       push alone, stack empty
//   bin  1  PUSH x MID    - LIFO-PUSH       push alone, stack neither empty nor full
//   bin  2  PUSH x FULL   - LIFO-OVERFLOW   push alone, stack full
//   bin  3  POP  x EMPTY  - LIFO-UNDERFLOW  pop alone, stack empty
//   bin  4  POP  x MID    - LIFO-POP        pop alone, stack neither empty nor full
//   bin  5  POP  x FULL   - LIFO-POP        pop alone, stack full
//   bin  6  BOTH x EMPTY  - LIFO-BOTH-EMPTY push and pop together, stack empty
//   bin  7  BOTH x MID    - LIFO-REPLACE    push and pop together, stack neither empty nor full
//   bin  8  BOTH x FULL   - LIFO-REPLACE    push and pop together, stack full
//   bin  9  occupancy 0   - (all)           stack reaches fill level 0
//   bin 10  occupancy 1   - (all)           stack reaches fill level 1
//   bin 11  occupancy 2   - (all)           stack reaches fill level 2
//   bin 12  occupancy 3   - (all)           stack reaches fill level 3
//   bin 13  occupancy 4   - (all)           stack reaches fill level 4
//   bin 14  reset         - LIFO-RESET      rst_n low at an edge while the stack holds a word (count != 0)
//
// Exclusions: none. The matrix waives no scenario and names no unreachable scenario.
//   planned = 15. holes = the number of planned bins not yet hit.

module lifo4_fcov (
    input  logic       clk, rst_n, push, pop,
    input  logic [7:0] din, dout,
    input  logic [2:0] count,
    input  logic       empty, full, err,
    output int         planned,   // how many bins the model plans
    output int         holes      // how many of them have not been hit yet
);

    /* verilator lint_off UNUSEDSIGNAL */
    logic [7:0] unused_din;
    logic [7:0] unused_dout;
    logic       unused_flags;
    assign unused_din   = din;
    assign unused_dout  = dout;
    assign unused_flags = empty ^ full ^ err;
    /* verilator lint_on UNUSEDSIGNAL */

    localparam int NBINS = 15;

    logic [NBINS-1:0] hit = '0;

    logic occ_empty, occ_full, occ_mid;
    logic op_push, op_pop, op_both;

    assign occ_empty = (count == 3'd0);
    assign occ_full  = (count == 3'd4);
    assign occ_mid   = (count >= 3'd1) && (count <= 3'd3);

    assign op_push = (push == 1'b1) && (pop == 1'b0);
    assign op_pop  = (push == 1'b0) && (pop == 1'b1);
    assign op_both = (push == 1'b1) && (pop == 1'b1);

    always @(posedge clk) begin
        if (rst_n == 1'b1) begin
            // operation x occupancy crosses
            if (op_push && occ_empty) hit[0] <= 1'b1;
            if (op_push && occ_mid)   hit[1] <= 1'b1;
            if (op_push && occ_full)  hit[2] <= 1'b1;
            if (op_pop  && occ_empty) hit[3] <= 1'b1;
            if (op_pop  && occ_mid)   hit[4] <= 1'b1;
            if (op_pop  && occ_full)  hit[5] <= 1'b1;
            if (op_both && occ_empty) hit[6] <= 1'b1;
            if (op_both && occ_mid)   hit[7] <= 1'b1;
            if (op_both && occ_full)  hit[8] <= 1'b1;
            // occupancy levels
            if (count == 3'd0) hit[9]  <= 1'b1;
            if (count == 3'd1) hit[10] <= 1'b1;
            if (count == 3'd2) hit[11] <= 1'b1;
            if (count == 3'd3) hit[12] <= 1'b1;
            if (count == 3'd4) hit[13] <= 1'b1;
        end else if (rst_n == 1'b0) begin
            // reset applied while the stack holds a word
            if (count != 3'd0 && count <= 3'd4) hit[14] <= 1'b1;
        end
    end

    always_comb begin
        int n;
        n = 0;
        for (int i = 0; i < NBINS; i++) begin
            if (!hit[i]) n = n + 1;
        end
        holes = n;
    end

    assign planned = NBINS;

endmodule
